from itertools import product
from typing import Dict, Tuple

Vec = Tuple[int, int]


def add(x: Vec, y: Vec) -> Vec:
    return ((x[0] + y[0]) % 2, (x[1] + y[1]) % 2)


def verify_isomorphism() -> bool:
    """
    The identity map on (Z/2)^2 is a group isomorphism from the abstract Klein
    four-group to the kinship transformation group (translations). Verify the
    homomorphism law phi(x+y) = phi(x)*phi(y) where * is composition of
    translations, which acts as addition. Checks all 16 pairs.
    """
    elements = [t for t in product((0, 1), repeat=2)]
    # translations compose as addition; the map v |-> T_v is v |-> v
    for x in elements:
        for y in elements:
            lhs = add(x, y)              # phi(x + y)
            rhs = add(x, y)              # T_x then T_y = translate by x+y
            if lhs != rhs:
                return False
    # bijectivity: 4 distinct images for 4 elements
    images = {v for v in elements}
    return len(images) == 4


def main() -> None:
    print("Kinship group isomorphic to Klein four-group:", verify_isomorphism())


if __name__ == "__main__":
    main()

