from itertools import product
from typing import Dict, List, Tuple

Vec = Tuple[int, ...]


def add(x: Vec, y: Vec) -> Vec:
    """Coordinatewise addition modulo 2 in (Z/2)^n."""
    return tuple((a + b) % 2 for a, b in zip(x, y))


def build_kinship_group(n: int) -> Dict[str, object]:
    """
    Construct the elementary abelian 2-group (Z/2)^n as a kinship
    transformation group. Returns its elements, Cayley table, and the
    generating kinship relations (mother, spouse, father for n>=2).
    """
    elements: List[Vec] = [t for t in product((0, 1), repeat=n)]
    cayley: Dict[Tuple[Vec, Vec], Vec] = {
        (x, y): add(x, y) for x in elements for y in elements
    }
    generators: Dict[str, Vec] = {}
    if n >= 2:
        mother = tuple(1 if i == n - 1 else 0 for i in range(n))
        spouse = tuple(1 if i == 0 else 0 for i in range(n))
        father = add(spouse, mother)
        generators = {"mother": mother, "spouse": spouse, "father": father}
    return {"elements": elements, "cayley": cayley, "generators": generators}

