from itertools import product
from typing import List, Tuple

Section = Tuple[int, int]


def add(x: Section, y: Section) -> Section:
    return ((x[0] + y[0]) % 2, (x[1] + y[1]) % 2)


def matrimoiety_coset(g: Section) -> frozenset:
    """Coset of the matrimoiety subgroup M = {(0,0),(1,0)} containing g."""
    M: List[Section] = [(0, 0), (1, 0)]
    return frozenset(add(g, m) for m in M)


def may_marry(x: Section, y: Section) -> bool:
    """
    Decide marriage eligibility: distinct sections x, y may intermarry iff
    they lie in the same coset of the matrimoiety subgroup, equivalently
    y = x + (1,0). Runs in O(1).
    """
    return x != y and matrimoiety_coset(x) == matrimoiety_coset(y)

