from itertools import product
from typing import Dict, List, Tuple

Sub = Tuple[int, int, int]
Sec = Tuple[int, int]


def forget(t: Sub) -> Sec:
    """Forgetful map q(a,b,c) = (a,b): Sub_8 -> Sec_4."""
    return (t[0], t[1])


def double_cover_data() -> Dict[str, object]:
    """
    Exhibit Sub_8 = (Z/2)^3 as a Z/2 double cover of Sec_4 = (Z/2)^2 via q.
    Returns the kernel (order 2), the surjective image, and the two-element
    fibers over each section, verifying |Sub_8| = 2 * |Sec_4|.
    """
    subs: List[Sub] = [t for t in product((0, 1), repeat=3)]
    kernel: List[Sub] = [t for t in subs if forget(t) == (0, 0)]
    image: List[Sec] = sorted({forget(t) for t in subs})
    fibers: Dict[Sec, List[Sub]] = {
        s: [t for t in subs if forget(t) == s] for s in image
    }
    return {"kernel": kernel, "image": image, "fibers": fibers,
            "cover_degree": len(subs) // len(image)}

