import matplotlib.pyplot as plt

def main() -> None:
    # Positions of the four sections at the corners of a square
    pos = {(0, 0): (0, 0), (1, 0): (2, 0), (0, 1): (0, 2), (1, 1): (2, 2)}
    names = {(0, 0): "A", (1, 0): "B", (0, 1): "C", (1, 1): "D"}
    add = lambda x, y: ((x[0] + y[0]) % 2, (x[1] + y[1]) % 2)
    gens = {"spouse": (1, 0), "mother": (0, 1), "father": (1, 1)}
    colors = {"spouse": "crimson", "mother": "royalblue", "father": "seagreen"}

    fig, ax = plt.subplots(figsize=(6, 6))
    for g, v in gens.items():
        for x in pos:
            y = add(x, v)
            x0, y0 = pos[x]; x1, y1 = pos[y]
            ax.annotate("", xy=(x1, y1), xytext=(x0, y0),
                        arrowprops=dict(arrowstyle="-", color=colors[g], lw=2,
                                        alpha=0.6))
    for s, (px, py) in pos.items():
        ax.scatter([px], [py], s=1200, color="white", edgecolors="black", zorder=3)
        ax.text(px, py, names[s], ha="center", va="center", fontsize=16, zorder=4)
    handles = [plt.Line2D([0], [0], color=c, lw=3, label=g)
               for g, c in colors.items()]
    ax.legend(handles=handles, loc="upper center", ncol=3, bbox_to_anchor=(0.5, 1.1))
    ax.set_title("Cayley graph of the four-section kinship group (Klein four)")
    ax.set_xlim(-1, 3); ax.set_ylim(-1, 3.2); ax.axis("off")
    plt.tight_layout(); plt.savefig("cayley_graph.png", dpi=150)
    print("Saved cayley_graph.png")


if __name__ == "__main__":
    main()
